446	            Sheet parent = sheets.findById(parentId)
447	                    .orElseThrow(() -> new ParentRefusedException("The parent must be a sheet that has been loaded."));
448	            Set<String> seen = new HashSet<>();
449	            for (Sheet up = parent; up != null && seen.add(up.getId());
450	                    up = up.getParentId() == null ? null : sheets.findById(up.getParentId()).orElse(null)) {
451	                if (sheetId.equals(up.getParentId())) {
452	                    throw new ParentRefusedException("The parent cannot be a sheet that has this sheet as an ancestor.");
